package com.bank.transfer;

import org.junit.jupiter.api.Test;
import org.springframework.kafka.core.KafkaTemplate;
import java.math.BigDecimal;
import java.util.concurrent.CompletableFuture;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

class TransferEventPublisherUnitTest {
    @Test
    void publishesToCorrectTopicAndKey() {
        @SuppressWarnings("unchecked")
        KafkaTemplate<String, Object> template = mock(KafkaTemplate.class);
        when(template.send(anyString(), anyString(), any()))
            .thenReturn(CompletableFuture.completedFuture(null));

        TransferEventPublisher publisher = new TransferEventPublisher(template);
        publisher.publish("SAV2001", new BigDecimal("50000"));

        // Pure unit test: no broker; assert the interaction only.
        verify(template).send(eq("transfer.completed"), eq("SAV2001"), any());
    }
}
