package com.bank.transfer;

import org.junit.jupiter.api.Test;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.kafka.test.context.EmbeddedKafka;
import org.springframework.beans.factory.annotation.Autowired;
import java.math.BigDecimal;
import java.util.concurrent.TimeUnit;

@SpringBootTest
@EmbeddedKafka(partitions = 1, topics = "transfer.completed")
class SettlementIntegrationTest {
    @Autowired KafkaTemplate<String, Object> template;
    @Autowired SettlementListener listener; // counts down a latch on receive

    @Test
    void producerToConsumerEndToEnd() throws InterruptedException {
        template.send("transfer.completed", "SAV2001",
            new TransferEvent("TXN-1", "SAV2001", new BigDecimal("50000")));
        // Wait on the real asynchronous consumption — never a fixed sleep.
        boolean received = listener.getLatch().await(5, TimeUnit.SECONDS);
        org.junit.jupiter.api.Assertions.assertTrue(received);
    }
}
