// ─── File: src/main/java/com/bank/transfer/demo/TestingStylesDemo.java ───
// Runnable demo modelling both testing styles: mock template + embedded broker + latch.
package com.bank.transfer.demo;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class TestingStylesDemo {

    private static final Logger log = Logger.getLogger("KafkaTest");
    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws InterruptedException {
        log.info("=== UNIT TEST style: mock template, assert the send call ===");
        MockKafkaTemplate mock = new MockKafkaTemplate();
        TransferEventPublisher publisher = new TransferEventPublisher(mock);
        publisher.publish("SAV2001", new BigDecimal("50000"));
        boolean correct = mock.sent("transfer.completed", "SAV2001");
        log.info(() -> "verify send(topic,key) matched = " + correct);

        log.info("=== INTEGRATION TEST style: embedded broker + latch, end to end ===");
        EmbeddedBroker broker = new EmbeddedBroker();
        CountDownLatch latch = new CountDownLatch(1);
        SettlementListener listener = new SettlementListener(latch);
        broker.subscribe("transfer.completed", listener::onEvent);

        RealKafkaTemplate real = new RealKafkaTemplate(broker);
        real.send("transfer.completed", "SAV2001",
            new TransferEvent("TXN-1", "SAV2001", new BigDecimal("50000")));

        boolean received = latch.await(5, TimeUnit.SECONDS);
        log.info(() -> "consumer received end-to-end = " + received);
    }
}

// ─── Would be in TransferEvent.java ───
class TransferEvent {
    final String txnId; final String accountId; final BigDecimal amount;
    TransferEvent(String txnId, String accountId, BigDecimal amount) {
            this.txnId = txnId;
            this.accountId = accountId
            this.amount = amount;
    }
}

// ─── Would be in KafkaTemplatePort.java (abstraction so we can mock or run real) ───
interface KafkaTemplatePort {
    void send(String topic, String key, TransferEvent event);
}

// ─── Would be in TransferEventPublisher.java (class under test) ───
class TransferEventPublisher {
    private static final Logger log = Logger.getLogger("KafkaTest");
    private final KafkaTemplatePort template;
    TransferEventPublisher(KafkaTemplatePort template) { this.template = template; }
    void publish(String accountId, BigDecimal amount) {
        TransferEvent event = new TransferEvent("TXN-1", accountId, amount);
        template.send("transfer.completed", accountId, event);
        log.fine(() -> "published event for " + accountId);
    }
}

// ─── Would be in MockKafkaTemplate.java (records interactions, no broker) ───
class MockKafkaTemplate implements KafkaTemplatePort {
    private final List<String> calls = new ArrayList<>();
    public void send(String topic, String key, TransferEvent event) {
        calls.add(topic + "|" + key);
    }
    boolean sent(String topic, String key) { return calls.contains(topic + "|" + key); }
}

// ─── Would be in EmbeddedBroker.java (models @EmbeddedKafka in-JVM broker) ───
class EmbeddedBroker {
    private final java.util.Map<String, java.util.function.Consumer<TransferEvent>> subs
            = new java.util.HashMap<>();
    void subscribe(String topic, java.util.function.Consumer<TransferEvent> handler) {
        subs.put(topic, handler);
    }
    void publish(String topic, TransferEvent event) {
        // Deliver asynchronously, like a real broker + listener container thread.
        var handler = subs.get(topic);
        if (handler != null) new Thread(() -> handler.accept(event)).start();
    }
}

// ─── Would be in RealKafkaTemplate.java (real send path through the broker) ───
class RealKafkaTemplate implements KafkaTemplatePort {
    private final EmbeddedBroker broker;
    RealKafkaTemplate(EmbeddedBroker broker) { this.broker = broker; }
    public void send(String topic, String key, TransferEvent event) {
        broker.publish(topic, event);
    }
}

// ─── Would be in SettlementListener.java (counts down a latch on receive) ───
class SettlementListener {
    private static final Logger log = Logger.getLogger("KafkaTest");
    private final CountDownLatch latch;
    SettlementListener(CountDownLatch latch) { this.latch = latch; }
    void onEvent(TransferEvent e) {
        log.info(() -> "settled txn=" + e.txnId + " account=" + e.accountId
                + " amount=Rs." + e.amount);
        latch.countDown();   // signal the test that consumption happened
    }
    CountDownLatch getLatch() { return latch; }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
